import Container from "@mui/material/Container";
import Card from "@mui/material/Card";
import CardContent from "@mui/material/CardContent";
import Typography from "@mui/material/Typography";
import Divider from "@mui/material/Divider";
//
import ToggleButton from "@mui/material/ToggleButton";
import ToggleButtonGroup from "@mui/material/ToggleButtonGroup";
//
import Todo from "./Todo";
//72
import Grid from "@mui/material/Grid";
import TextField from "@mui/material/TextField";
import Button from "@mui/material/Button";

//74
import { useState, useEffect } from "react";
import { TodosContext } from "../contexts/todosContext";
import { useContext } from "react";
import { v4 as uuidv4 } from "uuid";

export default function TodoList() {
  const { todos, setTodos } = useContext(TodosContext);
  const [titleInput, setTitleInput] = useState("");
  const [displayedTodosType, setDisplayedTodosType] = useState("all");

  const todosJsx = todos.map((t) => {
    return <Todo key={t.id} todo={t} />;
  });

  const compeletedTodos = todos.filter((t) => {
    return t.isCompleted;
  });

  useEffect(() => {
    const storageTodos = JSON.parse(localStorage.getItem("todos"));
    setTodos(storageTodos);
  }, []);

  function handleAddClick() {
    const newTodo = {
      id: uuidv4(),
      title: titleInput,
      details: "",
      isCompleted: false,
    };
    // setTodos([...todos, newTodo]); // هنا انا بعمل نسخه من المصفوفه القديمه واضيف عليها الجديده
    const updatedTodos = [...todos, newTodo];
    setTodos(updatedTodos);
    localStorage.setItem("todos", JSON.stringify(updatedTodos)); // هنا انا بعمل نسخه من المصفوفه القديمه واضيف عليها الجديده
    setTitleInput(""); // هنا انا بمسح محتوى الحقل بعد اضافه المهمه
  }

  // Wrong والحل بتاعه ف الفيديو ٨٠

  return (
    <>
      <Container maxWidth="sm">
        <Card sx={{ minWidth: 275 }}>
          <CardContent>
            <Typography variant="h2">مهامي</Typography>
            <Divider />

            {/* Filter Buttons */}
            <ToggleButtonGroup
              style={{ direction: "ltr", marginTop: "30px" }}
              value={displayedTodosType}
              exclusive
              // onChange={handleAlignment}
              aria-label="text alignment"
            >
              <ToggleButton value="right">غير المنجز </ToggleButton>
              <ToggleButton value="center">المنحز </ToggleButton>
              <ToggleButton value="all">الكل </ToggleButton>
            </ToggleButtonGroup>

            {/* Todo Item */}
            {todosJsx}

            {/* Input + ADD Button */}
            <Grid
              container
              style={{
                marginTop: "20px",
              }}
              spacing={2}
            >
              <Grid
                size={8}
                display="flex"
                justifyContent="space-around"
                alignItems="center"
              >
                <TextField
                  style={{ width: "100%" }}
                  id="outlined-basic"
                  value={titleInput}
                  onChange={(e) => {
                    setTitleInput(e.target.value);
                  }}
                  label="عنوان المهمه"
                  variant="outlined"
                />
              </Grid>

              <Grid
                size={4}
                display="flex"
                justifyContent="space-around"
                alignItems="center"
              >
                <Button
                  style={{ width: "100%", height: "100%" }}
                  variant="contained"
                  onClick={() => {
                    handleAddClick();
                  }}
                >
                  اضافه
                </Button>
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      </Container>
    </>
  );
}
